package org.brightstats.desktop;

import java.util.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.geometry.Insets;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class ImputationDialog {
    private ImputationDialog(){}
    static Optional<ImputedSem.Options> show(Window owner,ImputedSem.Options current){Dialog<ImputedSem.Options> dialog=new Dialog<>();dialog.initOwner(owner);dialog.setTitle("Multiple imputation and pooled SEM");dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);Spinner<Integer> count=new Spinner<>(2,100,current.imputation().imputations()),burn=new Spinner<>(20,2000,current.imputation().burnIterations());count.setEditable(true);burn.setEditable(true);count.setId("imputation-count");burn.setId("imputation-burn");TextField seed=new TextField(Long.toString(current.imputation().seed())),df=new TextField(current.completeDegreesOfFreedom()==null?"":current.completeDegreesOfFreedom().toString());df.setPromptText("Blank: large complete-sample assumption");CheckBox sandwich=new CheckBox("Use case-score sandwich covariance within each analysis");sandwich.setSelected(current.sandwichCovariance());Label error=new Label();error.setId("imputation-error");Label note=new Label("Continuous joint-normal imputation with independent seeded chains, then a complete-data SEM for each imputation and Rubin pooling. Original observed cells are preserved. Inspect traces and missingness assumptions. This is not an ordinal or MNAR imputer, and may be incompatible with nonlinear scientific models.");note.setWrapText(true);note.setMaxWidth(650);GridPane grid=new GridPane();grid.setHgap(12);grid.setVgap(10);Control[] fields={count,burn,seed,df};String[] names={"Imputations","Burn-in iterations per chain","Seed","Optional complete-data degrees of freedom"};for(int i=0;i<fields.length;i++){grid.add(new Label(names[i]),0,i);grid.add(fields[i],1,i);fields[i].setAccessibleText(names[i]);}VBox content=new VBox(12,note,grid,sandwich,error);content.setPadding(new Insets(15));dialog.getDialogPane().setContent(content);ImputedSem.Options[] result={null};dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{result[0]=new ImputedSem.Options(new GaussianImputation.Options(Integer.parseInt(count.getEditor().getText().strip()),Integer.parseInt(burn.getEditor().getText().strip()),Long.parseLong(seed.getText().strip())),current.analysis(),df.getText().isBlank()?null:Double.valueOf(df.getText().strip()),sandwich.isSelected());}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?result[0]:null);return dialog.showAndWait();}
    static ImputedSem.Options smoke(Window owner,ImputedSem.Options current,java.nio.file.Path image)throws Exception{Throwable[] failure={null};javafx.application.Platform.runLater(()->{javafx.stage.Window window=null;try{window=javafx.stage.Window.getWindows().stream().filter(w->w instanceof javafx.stage.Stage stage&&stage.getTitle().equals("Multiple imputation and pooled SEM")).findFirst().orElseThrow();var root=window.getScene().getRoot();var pane=(DialogPane)root.lookup(".dialog-pane");var count=(Spinner<?>)root.lookup("#imputation-count");count.getEditor().setText("1");((Button)pane.lookupButton(ButtonType.OK)).fire();if(!window.isShowing())throw new AssertionError("Invalid imputation controls accepted");count.getEditor().setText(Integer.toString(current.imputation().imputations()));((Label)root.lookup("#imputation-error")).setText("");pane.applyCss();pane.layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,pane,1);((Button)pane.lookupButton(ButtonType.OK)).fire();}catch(Throwable error){failure[0]=error;if(window!=null)window.hide();}});var result=show(owner,current);if(failure[0]!=null)throw new AssertionError("Imputation dialog smoke failed",failure[0]);return result.orElseThrow(()->new AssertionError("Valid imputation settings not returned"));}
}
